import json, re, os, sys
from collections import defaultdict
from datetime import datetime

BASE = r'C:\\AI\\benchmark\\v2\\results-umay\\sandboxes\\umay-hizli__kapali\\ajan-veri-temizle'
file_path = os.path.join(BASE, 'siparisler.jsonl')
out_path = os.path.join(BASE, 'ozet.json')

TR_MONTHS = {
    'ocak':1,'şubat':2,'mart':3,'nisan':4,'mayıs':5,'haziran':6,
    'temmuz':7,'ağustos':8,'eylül':9,'ekim':10,'kasım':11,'aralık':12
}

def parse_date(s):
    s = s.strip()
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%d.%m.%Y'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    m = re.match(r'^(\d{1,2})\s+([A-Za-zÇçĞğİıÖöŞşÜü]+)\s+(\d{4})$', s)
    if m:
        gun = int(m.group(1))
        ay_adi = m.group(2).lower()
        yil = int(m.group(3))
        ay = TR_MONTHS.get(ay_adi)
        if ay is None:
            return None
        try:
            return datetime(yil, ay, gun)
        except ValueError:
            return None
    return None

def parse_amount(v):
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return float(v)
    if isinstance(v, str):
        s = v.replace('₺','').replace('TL','').replace('tl','').strip()
        s = s.replace(' ', '')
        if s == '':
            return None
        has_dot = '.' in s
        has_comma = ',' in s
        if has_dot and has_comma:
            s = s.replace('.', '').replace(',', '.')
        elif has_comma and not has_dot:
            s = s.replace(',', '.')
        elif has_dot and not has_comma:
            after = s.split('.')[-1]
            if len(after) == 3:
                s = s.replace('.', '')
        try:
            return float(s)
        except ValueError:
            return None
    return None

valid_records = {}
error_lines = 0
blank_lines = 0

with open(file_path, 'r', encoding='utf-8') as f:
    for line in f:
        stripped = line.strip()
        if stripped == '':
            blank_lines += 1
            continue
        try:
            obj = json.loads(stripped)
        except json.JSONDecodeError:
            error_lines += 1
            continue
        if not isinstance(obj, dict):
            error_lines += 1
            continue
        required = {'id','musteri','tutar','tarih','durum'}
        if not required.issubset(obj.keys()):
            error_lines += 1
            continue
        musteri = obj['musteri']
        if not isinstance(musteri, str):
            error_lines += 1
            continue
        musteri = musteri.strip()
        if musteri == '':
            error_lines += 1
            continue
        tutar = parse_amount(obj['tutar'])
        if tutar is None:
            error_lines += 1
            continue
        tarih = parse_date(obj['tarih'])
        if tarih is None:
            error_lines += 1
            continue
        durum = obj['durum']
        if not isinstance(durum, str):
            error_lines += 1
            continue
        durum_norm = durum.strip().lower()
        valid_records[obj['id']] = {
            'id': obj['id'],
            'musteri': musteri,
            'tutar': tutar,
            'tarih': tarih,
            'durum': durum_norm
        }

etkif_tutar = 0.0
aylik = defaultdict(float)
musteri_toplari = defaultdict(float)
iptal_sayisi = 0

for rec in valid_records.values():
    if rec['durum'] == 'iptal':
        iptal_sayisi += 1
        continue
    etkif_tutar += rec['tutar']
    aylik[rec['tarih'].strftime('%Y-%m')] += rec['tutar']
    musteri_toplari[rec['musteri']] += rec['tutar']

en_cok = max(musteri_toplari, key=musteri_toplari.get) if musteri_toplari else None

sonuc = {
    'gecerli_kayit': len(valid_records),
    'hatali_satir': error_lines,
    'iptal_sayisi': iptal_sayisi,
    'toplam_tutar': round(etkif_tutar, 2),
    'aylik': {k: round(v, 2) for k, v in sorted(aylik.items())},
    'en_cok_harcayan': en_cok
}

with open(out_path, 'w', encoding='utf-8') as f:
    json.dump(sonuc, f, ensure_ascii=False, indent=2)

print(json.dumps(sonuc, ensure_ascii=False, indent=2))
print('Blank:', blank_lines, 'Errors:', error_lines, 'Valid unique IDs:', len(valid_records))

